/* ================= DOCUMENTOS · permisos y operaciones ================= */
const relVis=id=>scoped().some(r=>r.id===id);
function carpVis(rel,c){const cf=C().carp[c]||{};if(can('doc.ver')&&role().alcance==='todos')return true;if(own(rel))return !!cf.emp;return can('doc.ver')&&!!cf.mgr}
function docVis(d){const r=get('relaciones',d.relId);return !!r&&relVis(d.relId)&&(carpVis(r,d.carpeta)||(own(r)&&d.estado==='Por revisar'))}
