function mkDoc(t,o){const d=Object.assign({id:nid('exd'),carpeta:'Personal',tipo:'PDF',contenido:'',tam:'',estadoFirma:'No requiere',fecha:TODAY,vence:'',estado:'Vigente',version:1,versiones:[],origen:'Subido',por:''},o);if(!d.tam)d.tam=Math.max(1,Math.round(d.contenido.length/90))*12+' KB';t.documentos.push(d);return d}
