const vPill=d=>{if(!d.vence)return'<span class="muted">—</span>';const n=days(TODAY,d.vence);return `<span class="num">${fd(d.vence)}</span> `+(n<0?pill('Vencido','crit'):n<=30?pill('Vence en '+n+' d','warn'):'')};
const ePill=d=>d.estado==='Archivado'?pill('Archivado'):d.estado==='Por revisar'?pill('Por revisar','warn'):d.estado==='Rechazado'?pill('Rechazado','crit'):pill('Vigente','ok');
function docTable(ds,showRel){return `<div class="tw"><table><thead><tr><th style="min-width:210px">Documento</th>${showRel?'<th>Colaborador</th>':''}<th>Carpeta</th><th>Fecha</th><th>Vence</th><th>Firma</th><th>Estado</th><th></th></tr></thead><tbody>${ds.map(d=>`<tr class="click" data-a="ex_docVer" data-id="${d.id}"><td><b>${esc(d.nombre)}</b><div class="muted">${esc(d.tipo)} · ${esc(d.tam)} · versión ${d.version}${d.origen==='Generado'?' · generado desde plantilla':''}</div></td>${showRel?`<td>${esc(relName(d.relId))}</td>`:''}<td>${esc(d.carpeta)}</td><td class="num">${fd(d.fecha)}</td><td style="white-space:nowrap">${vPill(d)}</td><td>${fPill(d)}</td><td>${ePill(d)}</td><td style="text-align:right"><button class="btn s" data-a="ex_docVer" data-id="${d.id}">Ver</button></td></tr>`).join('')}</tbody></table></div>`}
function sigBlock(doc){const s=T().ex_firmas.filter(x=>x.docId===doc.id&&x.estado!=='Anulado').pop();if(!s)return'';const f=s.firmantes.filter(x=>x.estado==='Firmado');if(!f.length)return'';
 return `<div class="ex_sig">${f.map(x=>`<div><i>${esc(x.nombreFirma)}</i><b>${esc(relName(x.relId))}</b><br>${esc(x.rol)} · ${fts(x.firmado)}<br><span class="mono">${x.via==='Presencial'?'Firma en físico registrada':'Firma electrónica · cód. '+esc(x.codigo||'')}</span></div>`).join('')}</div><div class="mono muted" style="margin-top:14px;font-size:11px">Huella del documento: ${s.huella}</div>`}

