 const acum=Math.round(days(i.ini,addDays(hasta,1))/30.4375*10)/10;
 if(r.contratoTipo==='Plazo fijo'&&acum>C().topeMeses)return 'Con esta renovación acumularía '+acum+' meses a plazo fijo y supera el tope configurado de '+C().topeMeses+' meses. Reduce el plazo o actualiza el contrato a indeterminado desde la ficha.';
 const tpl=get('ex_plantillas','pl_adenda')||T().ex_plantillas.find(p=>/adenda/i.test(p.nombre));if(!tpl)return 'No existe la plantilla «Adenda de renovación de contrato». Créala en Documentos › Plantillas.';
 const desde=addDays(r.contratoFin,1),doc=genDoc(tpl,r,{'renovacion.desde':fl(desde),'renovacion.hasta':fl(hasta),'renovacion.motivo':motivo});doc.nombre='Adenda de renovación al '+fd(hasta);
 const p={id:nid('exc'),relId:r.id,tipo:'Renovación',modalidad:r.contratoTipo,desde,hasta,motivo,estado:'Por firmar',docId:doc.id,sobreId:''};T().ex_contratos.push(p);
