const encSync=()=>T().encuestas.forEach(e=>{if(e.estado==='Activa'&&e.cierre&&e.cierre<TODAY)e.estado='Cerrada'});
const encDest=e=>actAll().filter(r=>inSeg(r,e.seg));
const encResp=e=>T().encRespuestas.filter(x=>x.encuestaId===e.id);
const umb=e=>e.anonima?Math.max(2,Number(e.umbral)||C().umbral):1;
const partic=e=>{const d=encDest(e).length;return d?Math.min(100,Math.round(e.respondieron.length/d*100)):0};
const puedeResp=e=>{const m=me0();return !!m&&e.estado==='Activa'&&inSeg(m,e.seg)&&!e.respondieron.includes(m.id)};
const misEnc=()=>{encSync();return T().encuestas.filter(puedeResp)};
const ePill2=e=>pill(e.estado,e.estado==='Activa'?'ok':e.estado==='Borrador'?'warn':'');
