 ex_slaCfg:()=>{const s=C().sla;openForm(()=>({title:'Plazos de atención por categoría',note:'Horas corridas desde la creación de la solicitud. Aplican a las solicitudes nuevas y a las reaperturas.',fields:CATS.map(c=>({k:c,l:c+' (horas)',type:'number',req:1})),submit:o=>{for(const c of CATS)if(!(Number(o[c])>=1))return 'El plazo de «'+c+'» debe ser de al menos 1 hora.';const an=CATS.map(c=>c+' '+s[c]).join(' · ');CATS.forEach(c=>s[c]=Math.round(Number(o[c])));log('Edición de plazos de atención','Configuración','Mesa de ayuda','',an,CATS.map(c=>c+' '+s[c]).join(' · '));toast('Plazos guardados')}}),{...s})},
