function homeMesa(){const mr=me0(),ag=can('mesa.atender'),it=[];
 if(ag){const ur=T().tickets.filter(t=>TK_OPEN.includes(t.estado)&&(sla(t).out||sla(t).soon)).sort((a,b)=>sla(a).h-sla(b).h);
  ur.slice(0,5).forEach(t=>it.push([`<b>${t.codigo} · ${esc(t.asunto)}</b><div class="muted">${esc(relName(t.relId))} · ${esc(t.categoria)} · ${t.agenteId?esc(userName(t.agenteId)):'sin asignar'}</div>`,`${slaPill(t)}<button class="btn s" data-a="ex_tkAbrir" data-id="${t.id}">Abrir</button>`]));
  const n=T().tickets.filter(t=>t.estado==='Nuevo').length;if(n)it.push([`<b>${n} solicitud${n===1?'':'es'} nueva${n===1?'':'s'} sin atender</b><div class="muted">Asígnalas o tómalas desde la bandeja.</div>`,`<button class="btn s" data-a="ex_irMesa" data-t="band">Ir a la bandeja</button>`])}
 if(mr){T().tickets.filter(t=>tkMine(t)&&t.estado!=='Cerrado').forEach(t=>it.push([`<b>Mi solicitud ${t.codigo}: ${esc(t.asunto)}</b><div class="muted">${t.estado==='Resuelto'?'RRHH la resolvió: confirma y califica la atención.':t.estado==='Esperando información'?'RRHH necesita que respondas para continuar.':'En manos de RRHH · '+esc(sla(t).txt.toLowerCase())}</div>`,`${tkPill(t)}<button class="btn s ${t.estado==='Resuelto'||t.estado==='Esperando información'?'p':''}" data-a="ex_tkAbrir" data-id="${t.id}">Abrir</button>`]))}
 return it.length||(mr&&!ag)?`<div class="panel"><div class="ph"><h2>${ag?'Mesa de ayuda: solicitudes por vencer':'Mis solicitudes a RRHH'}</h2>${mr?'<button class="btn s" data-a="ex_tkNew">Nueva solicitud</button>':''}</div><div class="pb" style="padding-block:4px">${it.length?it.map(x=>`<div class="ex_li"><div style="min-width:0;flex:1 1 220px">${x[0]}</div><div class="row">${x[1]}</div></div>`).join(''):'<p class="muted" style="padding:10px 0">No tienes solicitudes abiertas. Pide aquí certificados, constancias o haz consultas sobre tu boleta y vacaciones.</p>'}</div></div>`:''}
function alertsMesa(){if(!can('mesa.atender'))return[];return T().tickets.filter(t=>TK_OPEN.includes(t.estado)&&sla(t).out).map(t=>({c:'crit',t:`Solicitud ${t.codigo} fuera de plazo: ${t.asunto}`,d:`${relName(t.relId)} espera respuesta desde el ${fts(t.creado)} y el plazo de ${C().sla[t.categoria]} horas para «${t.categoria}» ${sla(t).txt.toLowerCase()}. ${t.agenteId?'La tiene '+userName(t.agenteId)+'.':'Nadie la ha tomado: asígnala en Mesa de ayuda.'}`,rel:scoped().some(r=>r.id===t.relId)?t.relId:undefined}))}
function pendMesa(){const p=[],u=me().id;
 if(can('mesa.atender'))T().tickets.filter(t=>t.agenteId===u&&['Nuevo','En atención'].includes(t.estado)).forEach(t=>p.push({id:'t'+t.id,tipo:'Solicitud a RRHH',t:t.codigo+' · '+t.asunto,d:relName(t.relId)+' · '+sla(t).txt,relId:t.relId,abrir:{r:'ex_mesa'}}));
 T().tickets.filter(t=>tkMine(t)&&(t.estado==='Resuelto'||t.estado==='Esperando información')).forEach(t=>p.push({id:'m'+t.id,tipo:'Solicitud a RRHH',t:(t.estado==='Resuelto'?'Confirmar y calificar: ':'Responder a RRHH: ')+t.codigo,d:t.asunto,relId:t.relId,abrir:{r:'ex_mesa'}}));
 return p}
function seedMesa(t){const c=t.ex_cfg,N=id=>{const r=t.relaciones.find(x=>x.id===id),p=t.personas.find(x=>x.id===r.personaId);return p.nombres+' '+p.apellidos};
 const mk=(relId,cat,asunto,det,hCre,estado,ag,msgs,o)=>{const cre=hAgo(hCre),x=Object.assign({id:nid('ext'),codigo:'HR-'+String(++c.tkSeq).padStart(4,'0'),relId,categoria:cat,asunto,detalle:det,estado,creado:cre,venceSla:new Date(new Date(cre).getTime()+c.sla[cat]*36e5).toISOString(),agenteId:ag,mensajes:[{ts:cre,rol:'col',autor:N(relId),texto:det},...msgs.map(m=>({ts:hAgo(m[0]),rol:m[1],autor:m[2],texto:m[3],interno:!!m[4]}))],resuelto:'',cerrado:'',calif:0,califNota:'',reaperturas:0,docId:'',pausa:'',kbIds:[]},o||{});t.tickets.push(x);return x};
 mk('rl5','Consulta','Cómo actualizo mi cuenta de haberes','Cambié de banco y quiero que mi sueldo se deposite en la nueva cuenta. ¿Qué debo presentar?',400,'Cerrado','us2',[[396,'sys','Carmen Huamán Rojas','Nuevo → En atención'],[395,'ag','Carmen Huamán Rojas','Hola, Milagros. Envíanos la constancia de la cuenta emitida por tu banco y la registramos para la próxima planilla.'],[380,'sys','Carmen Huamán Rojas','En atención → Resuelto'],[370,'sys','Milagros Torres Luna','Resuelto → Cerrado · confirmada por el colaborador']],{resuelto:hAgo(380),cerrado:hAgo(370),calif:5,califNota:'Respuesta rápida y clara.'});
 mk('rl9','Vacaciones','Saldo de vacaciones para diciembre','Quiero saber cuántos días de vacaciones tengo disponibles para programar un viaje en diciembre.',96,'Resuelto','us2',[[90,'sys','Carmen Huamán Rojas','Nuevo → En atención'],[72,'ag','Carmen Huamán Rojas','Hola, Valeria. Tu saldo actualizado figura en el módulo de vacaciones. Para diciembre, envía la solicitud con al menos 15 días de anticipación para que tu jefe la apruebe.'],[72,'sys','Carmen Huamán Rojas','En atención → Resuelto']],{resuelto:hAgo(72)});
 mk('rl13','Beneficios','Reembolso de internet por teletrabajo','En la boleta de septiembre no veo la compensación de internet de mi acuerdo de teletrabajo.',30,'Esperando información','us2',[[28,'sys','Carmen Huamán Rojas','Nuevo → En atención'],[27,'ag','Carmen Huamán Rojas','Hola, Carlos. Para revisarlo necesito que me confirmes desde qué mes no lo recibes.'],[27,'sys','Carmen Huamán Rojas','En atención → Esperando información'],[26,'ag','Carmen Huamán Rojas','Revisar con Nómina si el concepto quedó inactivo al cambiar de periodo.',1]],{pausa:hAgo(27)});
 mk('rl10','Planilla','Diferencia en el pago de comisiones de septiembre','Mi comisión de septiembre salió menor a lo que calculé con mis ventas cerradas. Adjunté el detalle a mi jefe.',50,'En atención','us3',[[47,'sys','Milagros Torres Luna','Nuevo → En atención'],[46,'ag','Milagros Torres Luna','Hola, Kevin. Estoy revisando el cálculo con el reporte de ventas de Comercial. Te respondo apenas lo valide.']]);
 mk('rl17','Documentos','Copia de mi contrato y adendas','Necesito una copia de mi contrato y de las renovaciones para un trámite de alquiler.',42,'En atención','us2',[[40,'sys','Carmen Huamán Rojas','Nuevo → En atención']]);
 mk('rl14','Certificado','Certificado de trabajo para trámite bancario','Necesito un certificado de trabajo para presentarlo al banco por una cuenta de ahorros. ¿Me lo pueden emitir esta semana?',5,'Nuevo','',[]);
 const kb=(titulo,categoria,claves,cuerpo,vistas,si,no)=>{const votos={};for(let i=0;i<si;i++)votos['d'+i]=1;for(let i=0;i<no;i++)votos['n'+i]=-1;t.ex_kb.push({id:nid('exb'),titulo,categoria,claves,cuerpo,fecha:addDays(TODAY,-30-vistas%40),activo:true,vistas,votos})};
 kb('¿Cómo pido un certificado o una constancia de trabajo?','Certificado','certificado constancia trabajo banco trámite','1. Entra a Mesa de ayuda y elige «Nueva solicitud».\n2. Selecciona la categoría Certificado y cuenta para qué lo necesitas.\n3. RRHH lo genera con los datos de tu ficha y lo deja en tu carpeta Certificados, en Documentos.\n\nEl plazo de atención es el que figura al elegir la categoría. Si necesitas que la constancia indique tu remuneración, menciónalo en la solicitud.',64,18,1);
 kb('¿Cuándo se pagan las gratificaciones?','Planilla','gratificación julio diciembre pago fiestas patrias navidad','En el régimen laboral general hay dos gratificaciones al año: una por Fiestas Patrias (julio) y otra por Navidad (diciembre). Se pagan en la primera quincena de cada uno de esos meses.\n\nEl monto depende del tiempo trabajado en el semestre. Si ingresaste a mitad de semestre, recibes la parte proporcional.\n\nSi tu régimen es distinto al general (por ejemplo, microempresa), consulta a RRHH qué te corresponde.',120,31,2);
 kb('¿Cómo se calculan mis vacaciones?','Vacaciones','vacaciones días saldo récord descanso','En el régimen general, por cada año completo de servicios te corresponden 30 días calendario de descanso, siempre que cumplas el récord de asistencia.\n\nTu saldo aparece en el módulo de vacaciones. Las solicitudes las aprueba tu jefe directo y deben coordinarse con anticipación.\n\nSi tu régimen laboral es otro, el número de días puede variar: revisa tu contrato o consulta a RRHH.',98,24,3);
 kb('¿Qué es la CTS y cuándo se deposita?','Planilla','cts compensación tiempo servicios depósito mayo noviembre','La compensación por tiempo de servicios (CTS) es un beneficio que funciona como respaldo ante el cese. En el régimen general se deposita dos veces al año, en mayo y en noviembre, en la entidad financiera que elegiste.\n\nPuedes cambiar de entidad financiera presentando una solicitud en la categoría Planilla.',77,19,0);
 kb('Teletrabajo: compensación de gastos y desconexión digital','Beneficios','teletrabajo internet energía compensación desconexión reembolso','Si tienes un acuerdo de teletrabajo, la empresa compensa los gastos de internet y energía según lo pactado en tu acuerdo. El monto aparece en tu boleta como concepto no remunerativo.\n\nTienes derecho a desconectarte fuera de tu jornada, en tus descansos, licencias y vacaciones.\n\nSi no ves la compensación en tu boleta, envía una solicitud en la categoría Beneficios indicando el mes.',41,9,1);
 kb('¿Cómo actualizo mis datos personales?','Documentos','dirección teléfono datos personales emergencia actualizar','Desde tu ficha, en la pestaña Información, puedes actualizar tu teléfono, dirección y contacto de emergencia con el botón «Actualizar mis datos».\n\nPara cambios de nombre, documento o estado civil, sube el sustento en Documentos (carpeta Personal) y RRHH lo validará.',55,12,1);
 kb('¿Cómo firmo un documento en el sistema?','Documentos','firma electrónica firmar contrato adenda código','Cuando te envían un documento a firma, lo verás en tu Inicio y en Firma electrónica › Por firmar.\n\n1. Abre «Revisar y firmar» y lee el documento.\n2. Escribe tu nombre completo tal como figura en tu ficha.\n3. Ingresa el código de verificación que recibes.\n4. Marca la declaración y firma.\n\nQueda registrada la fecha, la hora y la huella del documento. Si no estás de acuerdo con el contenido, puedes rechazar la firma indicando el motivo.',38,11,0);
 kb('¿Qué hago si hay un error en mi boleta?','Planilla','boleta error descuento pago diferencia sueldo comisión','Revisa primero el detalle de ingresos y descuentos de tu boleta. Si encuentras una diferencia, envía una solicitud en la categoría Planilla indicando el periodo, el concepto y el monto que esperabas.\n\nSi el error se confirma, la regularización se paga en la siguiente planilla o en un pago aparte, según el caso.',47,10,2);
 t.tickets.find(x=>x.categoria==='Vacaciones').kbIds.push(t.ex_kb.find(a=>a.categoria==='Vacaciones').id)}
